c *Client) Submit(ctx context.Context, job Job) (string, error) {
	body, err := json.Marshal(job)
	if err != nil {
		return "", fmt.Errorf("encoding job: %w", err)
	}
	resp, err := c.post(ctx, "/v1/jobs", body)
	if err != nil {
		return "", fmt.Errorf("submitting job: %w", err)
	}
	return resp.ID, nil
}
